package org.delcom.ifs25019springbootcashflow.framework.view;
import com.vaadin.flow.component.grid.*; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.router.*; import org.delcom.ifs25019springbootcashflow.domain.Role; import org.delcom.ifs25019springbootcashflow.framework.auth.AuthSession; import org.delcom.ifs25019springbootcashflow.usecase.UserUseCase;
@Route(value="users", layout=MainLayout.class) public class UsersView extends VerticalLayout {public UsersView(UserUseCase use){var me=AuthSession.user();if(me==null||me.role()!=Role.ADMIN){getUI().ifPresent(ui->ui.navigate(""));return;}Grid<org.delcom.ifs25019springbootcashflow.domain.User> g=new Grid<>();g.addColumn(org.delcom.ifs25019springbootcashflow.domain.User::id).setHeader("ID");g.addColumn(org.delcom.ifs25019springbootcashflow.domain.User::username).setHeader("Username");g.addColumn(org.delcom.ifs25019springbootcashflow.domain.User::fullName).setHeader("Nama");g.addColumn(u->u.role().name()).setHeader("Role");GridStyles.apply(g);g.setItems(use.list());add(new H1("Daftar Pengguna"),g,new Anchor("user-transactions","Lihat transaksi pengguna (read-only)"),new Anchor("","Kembali"));}}
